const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');

const q = $('Webhook - Get Automation Runs').first().json.query || {};
const automationId = q.automation_id ? parseInt(q.automation_id, 10) : null;
const status = ['success', 'error', 'unsupported'].includes(q.status) ? q.status : null;
const limit = Math.min(Math.max(parseInt(q.limit, 10) || 50, 1), 200);
const offset = Math.max(parseInt(q.offset, 10) || 0, 0);

return [{ json: { automationId, status, limit, offset } }];

// alwaysOutputData means a genuinely empty page (offset past the end,
// or a filter matching nothing) still reaches here as zero items — total
// count would be lost with them, so re-derive it from a first-page item
// when there are results, and treat a truly empty result as count 0.
const rows = $input.all().map((i) => i.json).filter((r) => r.id != null);
const totalCount = rows.length > 0 ? Number(rows[0].total_count) : 0;
const runs = rows.map((r) => {
  const { total_count, ...rest } = r;
  return rest;
});
return [{ json: { success: true, runs, total_count: totalCount } }];

